import re
from typing import Dict, Tuple, Set

def parse_ini(text: str) -> dict[str, dict[str, str]]:
    sections: dict[str, dict[str, str]] = {}
    default_section: dict[str, str] = {}
    current_section: str | None = None
    current_key: str | None = None
    current_value: str = ""
    last_line_was_key: bool = False

    def remove_inline_comments(line: str) -> str:
        in_quotes = False
        result = []
        i = 0
        while i < len(line):
            if line[i] == '"':
                in_quotes = not in_quotes
                result.append(line[i])
                i += 1
            elif not in_quotes and line[i].isspace():
                # Check for comment start
                if i + 1 < len(line) and line[i+1] in (';', '#'):
                    # Comment starts here, cut the line
                    break
                result.append(line[i])
                i += 1
            else:
                result.append(line[i])
                i += 1
        return ''.join(result)

    lines = text.splitlines()
    for line_num, raw_line in enumerate(lines, 1):
        line = raw_line.rstrip('
')
        # Remove inline comments
        line = remove_inline_comments(line)
        # Skip empty lines
        if not line.strip():
            last_line_was_key = False
            continue
        # Check for continuation line
        if last_line_was_key and line.startswith((' ', '\t')):
            # Append to current value
            current_value += '
' + line.lstrip()
            continue
        # Not a continuation line, process as new line
        last_line_was_key = False
        # Section header?
        if line.startswith('[') and line.endswith(']'):
            section_name = line[1:-1].strip()
            current_section = section_name
            current_key = None
            current_value = ""
            sections[section_name] = {}
            continue
        # Key-value line?
        # Find first '=' or ':' that is not inside quotes
        in_quotes = False
        sep_pos = -1
        for i, ch in enumerate(line):
            if ch == '"':
                in_quotes = not in_quotes
            elif not in_quotes and ch in ('=', ':'):
                sep_pos = i
                break
        if sep_pos != -1:
            key_part = line[:sep_pos].strip()
            value_part = line[sep_pos+1:].strip()
            if not key_part:
                raise ValueError(f"Malformed key-value line at line {line_num}")
            key = key_part.lower()
            # Check for quoted value
            if value_part.startswith('"') and value_part.endswith('"'):
                value = value_part[1:-1]
            else:
                value = value_part
            # Store in current section or default
            if current_section is None:
                raise ValueError(f"Key line before any section at line {line_num}")
            if current_section == "DEFAULT":
                default_section[key] = value
            else:
                sections[current_section][key] = value
            current_key = key
            current_value = value
            last_line_was_key = True
            continue
        # If we get here, it's an invalid line
        raise ValueError(f"Malformed line at line {line_num}")

    # Interpolation
    def get_value(section_name: str, key: str) -> str:
        if key in sections.get(section_name, {}):
            return sections[section_name][key]
        if key in default_section:
            return default_section[key]
        raise KeyError(f"Key '{key}' not found in section '{section_name}'")

    def resolve_placeholder(placeholder: str, section_name: str, visited: Set[Tuple[str, str]]) -> str:
        if ':' in placeholder:
            parts = placeholder.split(':', 1)
            ref_section = parts[0]
            ref_key = parts[1]
            if ref_section == "DEFAULT":
                raise KeyError(f"Section 'DEFAULT' not found")
            if ref_section not in sections:
                raise KeyError(f"Section '{ref_section}' not found")
            try:
                ref_value = get_value(ref_section, ref_key)
            except KeyError as e:
                raise KeyError(f"Key '{ref_key}' not found in section '{ref_section}'") from e
        else:
            ref_key = placeholder
            ref_section = section_name
            try:
                ref_value = get_value(section_name, ref_key)
            except KeyError as e:
                raise KeyError(f"Key '{ref_key}' not found in section '{section_name}'") from e
        if (ref_section, ref_key) in visited:
            raise ValueError(f"Circular reference: ${placeholder}")
        visited.add((ref_section, ref_key))
        return interpolate_value(ref_value, ref_section, visited)

    def interpolate_value(value: str, section_name: str, visited: Set[Tuple[str, str]]) -> str:
        # Find all placeholders outside quotes
        in_quotes = False
        result = []
        i = 0
        while i < len(value):
            if value[i] == '"':
                in_quotes = not in_quotes
                result.append(value[i])
                i += 1
            elif not in_quotes and value.startswith('${', i):
                # Extract placeholder
                j = i + 2
                while j < len(value) and value[j] != '}':
                    j += 1
                if j == len(value):
                    raise ValueError(f"Malformed placeholder at line (placeholder not closed)")
                placeholder = value[i+2:j]
                resolved = resolve_placeholder(placeholder, section_name, visited)
                result.append(resolved)
                i = j + 1
            else:
                result.append(value[i])
                i += 1
        return ''.join(result)

    # Apply interpolation to all values
    for section_name, section_dict in sections.items():
        new_section_dict = {}
        for key, value in section_dict.items():
            visited: Set[Tuple[str, str]] = set()
            interpolated = interpolate_value(value, section_name, visited)
            new_section_dict[key] = interpolated
        sections[section_name] = new_section_dict

    return sections
