def summarize_ranges(nums: list[int]) -> str:
    if not nums:
        return ""
    sorted_nums = sorted(set(nums))
    n = len(sorted_nums)
    i = 0
    result = []
    while i < n:
        start = sorted_nums[i]
        j = i
        while j + 1 < n and sorted_nums[j + 1] == sorted_nums[j] + 1:
            j += 1
        end = sorted_nums[j]
        if end - start >= 2:
            result.append(f"{start}..{end}")
        else:
            result.append(str(start))
            if start != end:
                result.append(str(end))
        i = j + 1
    return ",".join(result)
